                tags: { type: array, items: { type: string } }
      responses:
        '201':
          description: Created. Metadata & snapshot enrich asynchronously.
          content: { application/json: { schema: { $ref: '#/components/schemas/Bookmark' } } }
        '200':
          description: >
            Duplicate normalized URL: returns the existing bookmark so the client
            opens it for editing (FR-006). `existing` is true.
          content:
            application/json:
              schema:
                allOf:
                  - $ref: '#/components/schemas/Bookmark'
                  - type: object
                    properties: { existing: { type: boolean, enum: [true] } }
        '400':
          description: Invalid web address (FR-004)
          content: { application/json: { schema: { $ref: '#/components/schemas/Error' } } }

  /api/bookmarks/{id}:
    parameters:
      - { name: id, in: path, required: true, schema: { type: string } }
    get:
      summary: Get one bookmark
      responses:
        '200': { description: OK, content: { application/json: { schema: { $ref: '#/components/schemas/Bookmark' } } } }
        '404': { description: Not found, content: { application/json: { schema: { $ref: '#/components/schemas/Error' } } } }
    patch:
      summary: Edit address, title, description, note, tags, read, archived (FR-008/021/022)
      requestBody:
        content:
          application/json:
            schema:
              type: object
              properties:
                url: { type: string }
                title: { type: string }
                description: { type: string }
                note: { type: string }
                tags: { type: array, items: { type: string } }
                read: { type: boolean }
                archived: { type: boolean }
      responses:
        '200': { description: Updated, content: { application/json: { schema: { $ref: '#/components/schemas/Bookmark' } } } }
        '400': { description: Invalid address or edit would collide with another bookmark's URL, content: { application/json: { schema: { $ref: '#/components/schemas/Error' } } } }
        '404': { description: Not found }
    delete:
      summary: Permanently delete a bookmark and its snapshot (FR-011)
      responses:
        '204': { description: Deleted }
        '404': { description: Not found }

  /api/bookmarks/{id}/snapshot:
    get:
      summary: Serve the stored local snapshot (self-contained HTML or PDF)
      parameters:
        - { name: id, in: path, required: true, schema: { type: string } }
      responses:
        '200':
          description: Snapshot bytes
          content:
            text/html: {}
            application/pdf: {}
        '404': { description: No snapshot available (pending/unavailable) }

  /api/bookmarks/{id}/web-archive:
    post:
      summary: Preserve the page via the Internet Archive and store the returned link (FR-030)
      parameters:
        - { name: id, in: path, required: true, schema: { type: string } }
      responses:
        '200':
          description: Archived; link stored on the bookmark
          content: { application/json: { schema: { type: object, properties: { webArchiveUrl: { type: string } } } } }
        '404': { description: Not found }
        '502': { description: Internet Archive unreachable; bookmark unchanged (best-effort) }

  /api/bookmarks/bulk:
    post:
      summary: Apply an action to many bookmarks (explicit ids or select-all-matching) (FR-024/025)
      requestBody:
        required: true
        content:
          application/json:
            schema:
              type: object
              required: [action]
              properties:
                ids:
                  type: array
                  items: { type: string }
                  description: Explicit selection. Omit when using `match`.
                match:
                  type: object
                  description: Select-all-matching the current view (FR-024)
                  properties:
                    view: { type: string, enum: [all, unread, archived] }
                    q: { type: string }
                    includeTags: { type: array, items: { type: string } }
                    excludeTags: { type: array, items: { type: string } }
                action:
                  type: string
                  enum: [addTag, removeTag, markRead, markUnread, archive, unarchive, delete]
                value:
                  type: string
                  description: Tag name for addTag/removeTag
                confirmDelete:
                  type: boolean
                  description: Must be true when action=delete (FR-025)
      responses:
        '200':
          description: Result summary
          content: { application/json: { schema: { type: object, properties: { affected: { type: integer } } } } }
        '400': { description: Missing confirmation for delete, or missing value for tag actions }

  /api/tags:
    get:
      summary: List tags with usage counts (for filtering and type-ahead suggestions) (FR-009)
      parameters:
        - { name: prefix, in: query, schema: { type: string }, description: "Optional prefix for suggestions" }
      responses:
        '200':
          description: Tags
          content:
            application/json:
              schema:
                type: array
                items:
                  type: object
                  properties: { name: { type: string }, count: { type: integer } }

  /api/filters:
    get:
      summary: List saved filters (FR-032)
      responses:
        '200': { description: OK, content: { application/json: { schema: { type: array, items: { $ref: '#/components/schemas/SavedFilter' } } } } }
    post:
      summary: Create a saved filter
      requestBody:
        required: true
        content: { application/json: { schema: { $ref: '#/components/schemas/SavedFilterInput' } } }
      responses:
        '201': { description: Created, content: { application/json: { schema: { $ref: '#/components/schemas/SavedFilter' } } } }
        '400': { description: Invalid (e.g. duplicate name) }

  /api/filters/{id}:
    parameters:
      - { name: id, in: path, required: true, schema: { type: string } }
    patch:
      summary: Edit a saved filter (never affects bookmarks)
      requestBody:
        content: { application/json: { schema: { $ref: '#/components/schemas/SavedFilterInput' } } }
      responses:
        '200': { description: Updated, content: { application/json: { schema: { $ref: '#/components/schemas/SavedFilter' } } } }
        '404': { description: Not found }
    delete:
      summary: Delete a saved filter
      responses:
        '204': { description: Deleted }
        '404': { description: Not found }

  /api/import:
    post:
      summary: Import a Netscape bookmarks HTML file (FR-026/027)
      requestBody:
        required: true
        content:
          multipart/form-data:
            schema:
              type: object
              properties:
                file: { type: string, format: binary }
      responses:
        '200':
          description: Import summary
          content:
            application/json:
              schema:
                type: object
                properties:
                  added: { type: integer }
                  skipped: { type: integer }
        '400': { description: Not a recognizable bookmarks file }

  /api/export:
    get:
      summary: Export the collection as a Netscape bookmarks HTML file (FR-028)
      responses:
        '200':
          description: Bookmarks file (tags as folders, dates preserved)
          content:
            text/html:
              schema: { type: string }

  /api/preferences:
    get:
      summary: Get display preferences (FR-033)
      responses:
        '200': { description: OK, content: { application/json: { schema: { $ref: '#/components/schemas/DisplayPreferences' } } } }
    put:
      summary: Update display preferences
      requestBody:
        required: true
        content: { application/json: { schema: { $ref: '#/components/schemas/DisplayPreferences' } } }
      responses:
        '200': { description: Updated, content: { application/json: { schema: { $ref: '#/components/schemas/DisplayPreferences' } } } }
        '400': { description: Out-of-range value }

