import { createApp } from './app.js';
import { getDb } from './db/connection.js';
import { registerHandler, enqueue } from './services/jobQueue.js';
import { runSnapshotJob } from './services/snapshot.js';
import { listPendingSnapshots } from './services/bookmarks.js';

const PORT = Number(process.env.PORT || 4000);
const HOST = '0.0.0.0';

// Initialize DB (runs migrations).
getDb();

// Register the background snapshot handler and recover interrupted captures.
registerHandler('snapshot', (payload) => runSnapshotJob(payload));

function recoverPendingSnapshots() {
  const pending = listPendingSnapshots();
  for (const bm of pending) {
    enqueue('snapshot', { bookmarkId: bm.id });
  }
  if (pending.length) {
    // eslint-disable-next-line no-console
    console.log(`[startup] re-enqueued ${pending.length} pending snapshot(s)`);
  }
}
recoverPendingSnapshots();

const app = createApp();
app.listen(PORT, HOST, () => {
  // eslint-disable-next-line no-console
  console.log(`Bookmark Manager listening on http://${HOST}:${PORT}`);
});

