:root {
  --fs: 16px;
  --bg: #f7f7f8;
  --panel: #ffffff;
  --border: #e2e2e6;
  --text: #1c1c22;
  --muted: #6b6b76;
  --accent: #2f6fed;
  --accent-weak: #eaf0fe;
  --danger: #d23b3b;
}
[data-font='small'] { --fs: 14px; }
[data-font='medium'] { --fs: 16px; }
[data-font='large'] { --fs: 18px; }

* { box-sizing: border-box; }
body {
  margin: 0;
  font-family: system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
  font-size: var(--fs);
  color: var(--text);
  background: var(--bg);
}
a { color: var(--accent); }

.layout { display: flex; min-height: 100vh; }
.sidebar {
  width: 210px;
  background: var(--panel);
  border-right: 1px solid var(--border);
  padding: 16px 12px;
  position: sticky;
  top: 0;
  height: 100vh;
}
.sidebar h1 { font-size: 1.1rem; margin: 0 0 16px; }
.nav a {
  display: block;
  padding: 8px 10px;
  border-radius: 8px;
  text-decoration: none;
  color: var(--text);
  margin-bottom: 2px;
}
.nav a.active { background: var(--accent-weak); color: var(--accent); font-weight: 600; }
.main { flex: 1; padding: 20px 28px; max-width: 960px; }

.toolbar { display: flex; gap: 10px; align-items: center; margin-bottom: 16px; flex-wrap: wrap; }
input[type='text'], input[type='search'], textarea, select {
  font: inherit;
  padding: 8px 10px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: #fff;
  color: var(--text);
}
.search { flex: 1; min-width: 220px; }
button {
  font: inherit;
  padding: 8px 12px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: #fff;
  cursor: pointer;
}
button.primary { background: var(--accent); color: #fff; border-color: var(--accent); }
button.danger { color: var(--danger); border-color: var(--danger); }
button:disabled { opacity: 0.5; cursor: default; }

.card {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 14px 16px;
  margin-bottom: 10px;
  display: flex;
  gap: 12px;
  align-items: flex-start;
}
.card .favicon { width: 20px; height: 20px; border-radius: 4px; flex-shrink: 0; margin-top: 2px; background: #eee; }
.card .body { flex: 1; min-width: 0; }
.card .title { font-weight: 600; margin: 0; }
.card .title a { text-decoration: none; }
.card .desc { color: var(--muted); margin: 4px 0; overflow: hidden; text-overflow: ellipsis; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; }
.card .meta { color: var(--muted); font-size: 0.85em; display: flex; gap: 10px; flex-wrap: wrap; align-items: center; }
.tag { background: var(--accent-weak); color: var(--accent); border-radius: 20px; padding: 1px 9px; font-size: 0.8em; }
.row-actions { display: flex; gap: 6px; flex-wrap: wrap; }
.row-actions button { padding: 4px 8px; font-size: 0.85em; }

.form { background: var(--panel); border: 1px solid var(--border); border-radius: 10px; padding: 18px; max-width: 640px; }
.form label { display: block; font-weight: 600; margin: 12px 0 4px; }
.form input[type='text'], .form textarea, .form input[type='search'] { width: 100%; }
.form textarea { min-height: 90px; resize: vertical; }
.hint { color: var(--muted); font-size: 0.85em; margin-top: 4px; }
.fallback { color: #a15c00; background: #fff6e5; padding: 6px 10px; border-radius: 8px; }
.empty { color: var(--muted); text-align: center; padding: 48px 0; }
.error { color: var(--danger); }
.bulkbar { background: var(--accent-weak); border: 1px solid var(--accent); border-radius: 10px; padding: 10px 14px; margin-bottom: 12px; display: flex; gap: 10px; align-items: center; flex-wrap: wrap; }
.tagsuggest { position: relative; }
.tagsuggest .menu { position: absolute; z-index: 5; background: #fff; border: 1px solid var(--border); border-radius: 8px; margin-top: 2px; width: 240px; max-height: 180px; overflow: auto; }
.tagsuggest .menu div { padding: 6px 10px; cursor: pointer; }
.tagsuggest .menu div:hover { background: var(--accent-weak); }
.chips { display: flex; gap: 6px; flex-wrap: wrap; margin-top: 6px; }
.chip { background: var(--accent-weak); color: var(--accent); border-radius: 20px; padding: 2px 8px; display: inline-flex; gap: 6px; align-items: center; }
.chip button { border: none; background: none; color: var(--accent); padding: 0; cursor: pointer; }
.markdown { border: 1px solid var(--border); border-radius: 8px; padding: 10px 12px; background: #fbfbfc; }
.markdown h1, .markdown h2, .markdown h3 { margin: 0.4em 0; }
.status-pill { font-size: 0.8em; padding: 1px 8px; border-radius: 20px; background: #eee; color: var(--muted); }
.status-pill.available { background: #e5f6ea; color: #1b7f43; }
.status-pill.pending { background: #fff6e5; color: #a15c00; }
.status-pill.unavailable { background: #fde8e8; color: var(--danger); }

