import { test, expect } from '@playwright/test';

// End-to-end happy path: add (with review) → list → search → edit → archive.
// Metadata/snapshot network steps degrade gracefully; the flow does not depend
// on them succeeding.
test('save, search, edit and archive a bookmark', async ({ page }) => {
  await page.goto('/');
  await expect(page.locator('body[data-harness-ready="true"]')).toBeVisible();

  // Add a bookmark
  await page.click('text=+ Add bookmark');
  await page.fill('input[placeholder="https://example.com/article"]', 'https://example.com/playwright-e2e');
  await page.click('text=Fetch details');
  // Review stage
  await page.fill('input:below(:text("Title"))>>nth=0', 'E2E Bookmark');
  await page.click('text=Save bookmark');

  // We land on the edit view; go to All
  await page.click('text=All bookmarks');
  await expect(page.locator('.card')).toContainText('E2E Bookmark');

  // Search
  await page.fill('input[type="search"]', 'E2E Bookmark');
  await expect(page.locator('.card')).toContainText('E2E Bookmark');

  // Archive from the row
  await page.click('.card >> text=Archive');
  await expect(page.locator('.empty')).toBeVisible();

  // Found in Archived
  await page.click('text=Archived');
  await expect(page.locator('.card')).toContainText('E2E Bookmark');
});

