import { test, expect } from '@playwright/test';

// End-to-end happy path: add (with review) → list → search → archive → find in
// Archived. Metadata/snapshot network steps degrade gracefully.
test('save, search and archive a bookmark', async ({ page }) => {
  await page.goto('/');
  await expect(page.locator('body[data-harness-ready="true"]')).toBeVisible();

  // Add a bookmark
  await page.click('text=+ Add bookmark');
  await page.fill('input[placeholder="https://example.com/article"]', 'https://example.com/playwright-e2e');
  await page.click('text=Fetch details');

  // Review stage: the first text input is the Title. Set a distinctive value.
  const titleInput = page.locator('.form input[type="text"]').first();
  await expect(titleInput).toBeVisible();
  await titleInput.fill('E2E Bookmark Zed');
  await page.click('text=Save bookmark');

  // Go to All and confirm it appears
  await page.click('text=All bookmarks');
  await expect(page.locator('.card').filter({ hasText: 'E2E Bookmark Zed' })).toBeVisible();

  // Search narrows the list
  await page.fill('input[type="search"]', 'E2E Bookmark Zed');
  await expect(page.locator('.card').filter({ hasText: 'E2E Bookmark Zed' })).toBeVisible();

  // Archive from the row
  await page
    .locator('.card')
    .filter({ hasText: 'E2E Bookmark Zed' })
    .getByRole('button', { name: 'Archive' })
    .click();

  // It appears in Archived
  await page.click('text=Archived');
  await expect(page.locator('.card').filter({ hasText: 'E2E Bookmark Zed' })).toBeVisible();
});

