import Database from 'better-sqlite3';
import { mkdirSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { runMigrations } from './migrations.js';

let db = null;
let currentPath = null;
let exitHookRegistered = false;

// better-sqlite3's native finalizer asserts if a connection is still open when
// the process exits; close it synchronously on exit to avoid that.
function registerExitHook() {
  if (exitHookRegistered) return;
  exitHookRegistered = true;
  process.once('exit', () => {
    try {
      if (db) db.close();
    } catch {
      /* ignore */
    }
  });
}

// Resolve the DB path from env (tests/e2e override it) or default to data/bookmarks.db.
export function dbPath() {
  return resolve(process.env.BOOKMARKS_DB || 'data/bookmarks.db');
}

export function getDb() {
  if (db) return db;
  const path = dbPath();
  mkdirSync(dirname(path), { recursive: true });
  db = new Database(path);
  db.pragma('journal_mode = WAL');
  db.pragma('foreign_keys = ON');
  runMigrations(db);
  currentPath = path;
  registerExitHook();
  return db;
}

// Close and reopen — used by the restart-persistence test to simulate a process
// restart against the same on-disk database.
export function closeDb() {
  if (db) {
    db.close();
    db = null;
    currentPath = null;
  }
}

export function reopenDb() {
  closeDb();
  return getDb();
}

export function activeDbPath() {
  return currentPath;
}

