let db = null;
let currentPath = null;
let sigHooked = false;

// Close cleanly on termination signals so a WAL checkpoint runs (server use).
// Note: we intentionally do NOT hook the 'exit' event — running SQLite during
// V8 env teardown can trip better-sqlite3's native finalizer assertion.
function registerSignalHooks() {
  if (sigHooked) return;
  sigHooked = true;
  for (const sig of ['SIGINT', 'SIGTERM']) {
    process.once(sig, () => {
      closeDb();
      process.exit(0);
    });
  }
}

