import { afterAll } from 'vitest';

// Close the SQLite connection at the end of every test file so no native handle
// stays open across files.
afterAll(async () => {
  try {
    const { closeDb } = await import('../../src/server/db/connection.js');
    closeDb();
  } catch {
    /* ignore */
  }
});

// better-sqlite3's Statement finalizer can trip a native assertion during V8
// environment teardown. When the worker's event loop finally drains (the true
// end of the run, not between files), force a clean exit before that teardown
// path runs. Registered once per worker.
if (!globalThis.__bmExitHooked) {
  globalThis.__bmExitHooked = true;
  process.once('beforeExit', (code) => {
    process.exit(typeof code === 'number' ? code : process.exitCode || 0);
  });
}

