import Database from 'better-sqlite3';
import { mkdirSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { runMigrations } from './migrations.js';

let db = null;
let currentPath = null;
let hooked = false;

// Close cleanly on exit/termination so no better-sqlite3 handle is finalized
// during teardown (which can trip its native assertion).
function registerHooks() {
  if (hooked) return;
  hooked = true;
  process.once('exit', () => {
    try {
      if (db) db.close();
    } catch {
      /* ignore */
    }
  });
  for (const sig of ['SIGINT', 'SIGTERM']) {
    process.once(sig, () => {
      closeDb();
      process.exit(0);
    });
  }
}

// Resolve the DB path from env (tests/e2e override it) or default to data/bookmarks.db.
export function dbPath() {
  return resolve(process.env.BOOKMARKS_DB || 'data/bookmarks.db');
}

export function getDb() {
  if (db) return db;
  const path = dbPath();
  mkdirSync(dirname(path), { recursive: true });
  db = new Database(path);
  db.pragma('foreign_keys = ON');
  runMigrations(db);
  currentPath = path;
  registerHooks();
  return db;
}

// Close and reopen — used by the restart-persistence test to simulate a process
// restart against the same on-disk database.
export function closeDb() {
  if (db) {
    db.close();
    db = null;
    currentPath = null;
  }
}

export function reopenDb() {
  closeDb();
  return getDb();
}

export function activeDbPath() {
  return currentPath;
}

import { defineConfig } from 'vitest/config';

export default defineConfig({
  test: {
    // Unit tests run in node; the markdown sanitize test opts into jsdom via a
    // per-file environment comment.
    environment: 'node',
    include: ['tests/unit/**/*.test.js', 'tests/api/**/*.test.js'],
    setupFiles: ['tests/helpers/setup.js'],
    globals: true,
    testTimeout: 20000,
    hookTimeout: 20000,
    // better-sqlite3 (native addon) segfaults when many instances run across
    // parallel workers; run all files sequentially in a single fork, and expose
    // GC so the setup hook can finalize sqlite statements before process exit.
    pool: 'forks',
    poolOptions: { forks: { singleFork: true } },
    fileParallelism: false,
  },
});

