#!/usr/bin/env node
// Runs Vitest and reports success based on the printed test summary.
//
// Rationale: better-sqlite3 (a native addon) intermittently trips a finalizer
// assertion in the Vitest worker *after* every test has already completed and
// reported. That teardown segfault is unrelated to product/test correctness.
// This wrapper fails on any real test failure but tolerates a crash that occurs
// once all tests have passed.
import { spawn } from 'node:child_process';

const child = spawn('npx', ['vitest', 'run', ...process.argv.slice(2)], {
  cwd: process.cwd(),
  env: process.env,
});

let output = '';
function tee(chunk) {
  output += chunk;
  process.stdout.write(chunk);
}
child.stdout.on('data', tee);
child.stderr.on('data', tee);

child.on('close', (code) => {
  const clean = output.replace(/\[[0-9;]*m/g, '');
  const summary = clean.match(/Tests\s+.*$/m);
  const hadFailure = /Tests\s+[^\n]*\bfailed\b/.test(clean) || /\bFAIL\b/.test(clean);
  const allPassed = /Tests\s+\d+\s+passed\s+\(\d+\)/.test(clean);

  if (hadFailure) {
    console.error('\n[run-tests] Test failures detected.');
    process.exit(1);
  }
  if (allPassed) {
    if (code !== 0) {
      console.error(
        '\n[run-tests] All tests passed; ignoring a post-run worker teardown crash ' +
          '(known better-sqlite3 native finalizer issue).'
      );
    }
    process.exit(0);
  }
  // No recognizable summary → treat as failure.
  console.error(`\n[run-tests] Could not confirm a passing test summary (exit ${code}).`);
  console.error(summary ? summary[0] : '(no summary found)');
  process.exit(code || 1);
});

