  const dir = mkdtempSync(join(tmpdir(), 'bm-'));
  process.env.BOOKMARKS_DB = join(dir, 'test.db');
  process.env.SNAPSHOT_DIR = join(dir, 'snapshots');
  const { reopenDb } = await import('../../src/server/db/connection.js');
